// ── Divider resize ────────────────────────────────────────────────
const divEl=document.getElementById('divider'),passEl=document.getElementById('passage'),qpEl=document.getElementById('qpanel');
let drag=false,splitRatio=null;
function applyPct(r){passEl.style.flex=r*100+' 1 0';passEl.style.width='';qpEl.style.flexBasis=(1-r)*100+'%';qpEl.style.flexShrink='1';qpEl.style.flexGrow='0';qpEl.style.width='';}
divEl.addEventListener('mousedown',()=>{drag=true;document.body.style.cursor='col-resize';document.body.style.userSelect='none';});
document.addEventListener('mousemove',e=>{if(!drag)return;const r=passEl.parentElement.getBoundingClientRect();const ratio=Math.min(Math.max((e.clientX-r.left)/(r.width-divEl.offsetWidth),0.15),0.85);splitRatio=ratio;applyPct(ratio);});
document.addEventListener('mouseup',()=>{drag=false;document.body.style.cursor='';document.body.style.userSelect='';});

// ── Clock & Battery ───────────────────────────────────────────────
const te=document.getElementById('timer');
function tick(){const n=new Date();te.textContent=String(n.getHours()).padStart(2,'0')+':'+String(n.getMinutes()).padStart(2,'0');}
tick();setInterval(tick,1000);


// ── Highlight & Note ──────────────────────────────────────────────
const HL_COLORS=['#8A4F7D'];
const noteStore=new Map();let noteIdCounter=0,savedRange=null;
function inAllowedArea(node){let el=node.nodeType===3?node.parentElement:node;while(el){if(el.id==='selection-popup'||el.id==='context-menu'||el.id==='note-panel')return false;if(el.classList&&(el.classList.contains('passage')||el.classList.contains('qpanel')))return true;el=el.parentElement;}return false;}
function restoreSelection(){if(savedRange){const s=window.getSelection();s.removeAllRanges();s.addRange(savedRange);}}
document.addEventListener('mouseup',function(e){const inP=e.target.closest('#selection-popup,#context-menu,#note-panel');if(inP)return;const sel=window.getSelection();if(!sel||sel.isCollapsed||sel.toString().trim()===''){handleClickOnMarkup(e);return;}const range=sel.getRangeAt(0);if(!inAllowedArea(range.commonAncestorContainer)){hideAllPopups();return;}savedRange=range.cloneRange();showSelectionPopup(e.clientX,e.clientY,range);});
function showSelectionPopup(x,y,range){hideAllPopups();const p=document.getElementById('selection-popup');const frag=range.cloneContents();const hasHl=!!frag.querySelector('.hl');const hasNote=!!frag.querySelector('.note-anchor');document.getElementById('sel-clear-hl-btn').style.display=hasHl?'flex':'none';document.getElementById('sel-clear-all-btn').style.display=hasHl?'flex':'none';document.getElementById('sel-clear-note-btn').style.display=hasNote?'flex':'none';document.getElementById('sel-div-extra').style.display=(hasHl||hasNote)?'flex':'none';p.style.left=Math.min(x,window.innerWidth-260)+'px';p.style.top=Math.max(y-70,10)+'px';p.style.display='flex';}
function applyHighlight(){restoreSelection();const sel=window.getSelection();if(!sel||sel.isCollapsed)return;const range=sel.getRangeAt(0);let maxLevel=-1;range.cloneContents().querySelectorAll('.hl').forEach(el=>{const l=parseInt(el.dataset.hlLevel??'-1');if(l>maxLevel)maxLevel=l;});const nxt=Math.min(maxLevel+1,HL_COLORS.length-1);try{const span=document.createElement('span');span.className='hl hl-active-part';span.dataset.hlLevel=nxt;span.style.backgroundColor=HL_COLORS[nxt];range.surroundContents(span);}catch(e){try{const ex=range.extractContents();const span=document.createElement('span');span.className='hl hl-active-part';span.dataset.hlLevel=nxt;span.style.backgroundColor=HL_COLORS[nxt];span.appendChild(ex);range.insertNode(span);}catch(e2){}}sel.removeAllRanges();hideAllPopups();}
function openNotePanel(x,y){hideAllPopups();const p=document.getElementById('note-panel');p.style.left=Math.min(x,window.innerWidth-210)+'px';p.style.top=Math.min(y+10,window.innerHeight-180)+'px';p.style.display='block';p.dataset.editingNoteId='';document.getElementById('note-textarea').value='';document.getElementById('note-textarea').focus();}
function saveNote(){const panel=document.getElementById('note-panel');const text=document.getElementById('note-textarea').value.trim();const eid=panel.dataset.editingNoteId;if(eid){noteStore.set(eid,text);const icon=document.querySelector(`.note-icon[data-note-id="${eid}"]`);if(icon)icon.title=text;if(!text)clearNoteById(eid);panel.style.display='none';return;}if(!text||!savedRange){panel.style.display='none';return;}restoreSelection();const sel=window.getSelection();if(!sel||sel.isCollapsed){panel.style.display='none';return;}const range=sel.getRangeAt(0);const nid='note-'+(++noteIdCounter);noteStore.set(nid,text);try{const anchor=document.createElement('span');anchor.className='note-anchor hl-active-part';anchor.dataset.noteId=nid;range.surroundContents(anchor);const icon=document.createElement('span');icon.className='note-icon';icon.dataset.noteId=nid;icon.title=text;icon.innerHTML=`<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#333" stroke-width="2.5"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>`;icon.addEventListener('click',e=>{e.stopPropagation();editNote(nid,e.clientX,e.clientY);});anchor.appendChild(icon);}catch(e){}sel.removeAllRanges();panel.style.display='none';}
function editNote(nid,x,y){const p=document.getElementById('note-panel');p.style.left=Math.min(x,window.innerWidth-210)+'px';p.style.top=Math.min(y+10,window.innerHeight-180)+'px';p.style.display='block';p.dataset.editingNoteId=nid;document.getElementById('note-textarea').value=noteStore.get(nid)||'';document.getElementById('note-textarea').focus();}
function handleClickOnMarkup(e){const hl=e.target.closest('.hl');const na=e.target.closest('.note-anchor');const ic=e.target.closest('.note-icon');if(!hl&&!na&&!ic){hideAllPopups();return;}const options=[];if(hl){options.push({label:'Clear Highlight',fn:()=>clearHighlight(hl)});options.push({label:'Clear all Highlights',fn:()=>clearAllHighlights()});}const anch=na||(ic?ic.closest('.note-anchor'):null);if(anch)options.push({label:'Clear Note',fn:()=>clearNoteById(anch.dataset.noteId)});if(options.length)showContextMenu(e.clientX,e.clientY,options);}
function clearHighlight(span){const p=span.parentNode;while(span.firstChild)p.insertBefore(span.firstChild,span);p.removeChild(span);p.normalize();hideAllPopups();}
function clearAllHighlights(){document.querySelectorAll('.hl-active-part').forEach(span=>{if(span.classList.contains('note-anchor')){span.classList.remove('hl-active-part');return;}const p=span.parentNode;while(span.firstChild)p.insertBefore(span.firstChild,span);p.removeChild(span);p.normalize();});hideAllPopups();}
function clearNoteById(nid){noteStore.delete(nid);document.querySelector(`.note-icon[data-note-id="${nid}"]`)?.remove();const a=document.querySelector(`.note-anchor[data-note-id="${nid}"]`);if(a){const p=a.parentNode;while(a.firstChild)p.insertBefore(a.firstChild,a);p.removeChild(a);p.normalize();}hideAllPopups();}
function showContextMenu(x,y,options){hideAllPopups();const menu=document.getElementById('context-menu');menu.innerHTML='';options.forEach(opt=>{const btn=document.createElement('button');btn.className='ctx-btn';btn.textContent=opt.label;btn.addEventListener('click',()=>opt.fn());menu.appendChild(btn);});menu.style.left=Math.min(x,window.innerWidth-190)+'px';menu.style.top=Math.min(y+5,window.innerHeight-160)+'px';menu.style.display='block';}
function hideAllPopups(){document.getElementById('selection-popup').style.display='none';document.getElementById('context-menu').style.display='none';}
document.getElementById('sel-highlight-btn').addEventListener('click',()=>applyHighlight());
document.getElementById('sel-note-btn').addEventListener('click',()=>{const p=document.getElementById('selection-popup');p.style.display='none';openNotePanel(parseFloat(p.style.left),parseFloat(p.style.top)+80);});
document.getElementById('sel-clear-hl-btn').addEventListener('click',()=>{restoreSelection();const sel=window.getSelection();if(sel&&!sel.isCollapsed){const range=sel.getRangeAt(0);const c=range.commonAncestorContainer.nodeType===3?range.commonAncestorContainer.parentElement:range.commonAncestorContainer;c.querySelectorAll('.hl').forEach(hl=>{if(range.intersectsNode(hl))clearHighlight(hl);});}hideAllPopups();});
document.getElementById('sel-clear-all-btn').addEventListener('click',()=>clearAllHighlights());
document.getElementById('sel-clear-note-btn').addEventListener('click',()=>{restoreSelection();const sel=window.getSelection();if(sel&&!sel.isCollapsed){const range=sel.getRangeAt(0);const c=range.commonAncestorContainer.nodeType===3?range.commonAncestorContainer.parentElement:range.commonAncestorContainer;c.querySelectorAll('.note-anchor').forEach(a=>{if(range.intersectsNode(a))clearNoteById(a.dataset.noteId);});}hideAllPopups();});
document.getElementById('note-save-btn').addEventListener('click',saveNote);
document.getElementById('note-close-btn').addEventListener('click',()=>document.getElementById('note-panel').style.display='none');
document.addEventListener('mousedown',function(e){if(!e.target.closest('#selection-popup,#context-menu,#note-panel')){document.getElementById('selection-popup').style.display='none';document.getElementById('context-menu').style.display='none';}});
